-- ============================================
-- LUMA — Thème 6 : 3e scénario COURT x4 — Partager les courses
-- ============================================


update scenarios set content = '{"characters": {"roommate": "ton/ta coloc"}, "start_node": "n1", "nodes": {"n1": {"speaker": "roommate", "text": "We''re almost out of basics — milk, bread, coffee. Want to do a shared shopping list?", "text_fr": "On n''a presque plus les bases — lait, pain, café. On fait une liste de courses commune ?", "choices": [{"text": "Yeah, let''s write it up together right now.", "text_fr": "Ouais, écrivons-la ensemble maintenant.", "next": "n2"}, {"text": "Sure — should we split costs evenly or by what each of us uses?", "text_fr": "Bien sûr — on partage les coûts équitablement ou selon ce que chacun utilise ?", "next": "n2b"}]}, "n2": {"speaker": "roommate", "text": "Great, I''ll add milk and bread, you add what you need.", "text_fr": "Super, j''ajoute le lait et le pain, ajoute ce dont tu as besoin.", "choices": [{"text": "I''ll add coffee and some fruit then.", "text_fr": "Je vais ajouter du café et des fruits alors.", "next": "n3"}]}, "n2b": {"speaker": "roommate", "text": "Good question — maybe split evenly for shared stuff, separate for personal items?", "text_fr": "Bonne question — peut-être partager équitablement pour les trucs communs, séparé pour les articles personnels ?", "choices": [{"text": "That makes sense, let''s do that.", "text_fr": "Ça se comprend, faisons ça.", "next": "n3"}]}, "n3": {"speaker": "roommate", "text": "Perfect. Do you want to go together, or should I just go and you pay me back?", "text_fr": "Parfait. On y va ensemble, ou j''y vais et tu me rembourses ?", "choices": [{"text": "Let''s go together, it''ll be quicker to split in the store.", "text_fr": "Allons-y ensemble, ce sera plus rapide de partager au magasin.", "next": "n4"}, {"text": "You go ahead, I''ll send you my share right after.", "text_fr": "Vas-y, je t''envoie ma part juste après.", "next": "n4b"}]}, "n4": {"speaker": "roommate", "text": "Sounds good, let''s head out in ten minutes.", "text_fr": "Ça marche, on y va dans dix minutes.", "choices": [{"text": "Perfect, I''ll grab my wallet.", "text_fr": "Parfait, je prends mon portefeuille.", "next": "n5"}]}, "n4b": {"speaker": "roommate", "text": "Works for me, I''ll text you the total once I''m done.", "text_fr": "Ça me va, je t''envoie le total une fois fini.", "choices": [{"text": "Sounds good, thanks for handling it.", "text_fr": "Ça marche, merci de t''en occuper.", "next": "n5"}]}, "n5": {"speaker": "roommate", "text": "This shared list thing is honestly going to save us so much hassle.", "text_fr": "Cette liste partagée va honnêtement nous épargner beaucoup de tracas.", "choices": [{"text": "Agreed, no more forgetting basics!", "text_fr": "D''accord, plus d''oubli des bases !", "next": "end_organized"}]}, "end_organized": {"speaker": "roommate", "text": "Exactly! Teamwork makes grocery shopping way less annoying.", "text_fr": "Exactement ! Le travail d''équipe rend les courses bien moins pénibles.", "end": true, "ending_label": "Courses organisées efficacement 🛒🤝"}}}'::jsonb, is_playable = true
where title = 'Partager les courses'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));
